head.script:
//
(function () {
  var key = "cgbum_theme";
  var raw = '';
  var m = document.cookie.match(new RegExp('(?:^|;\\s*)' + key + '=([^;]*)'));
  if (m && m[1]) {
    try { raw = decodeURIComponent(m[1]); } catch (e) { raw = m[1]; }
  }
  if (!raw) {
    try { raw = localStorage.getItem(key) || ''; } catch (e) {}
  }
  raw = String(raw || '').toLowerCase().trim().replace(/^["']+|["']+$/g, '');
  if (raw === 'dark' || raw === 'light') {
    document.documentElement.setAttribute('data-theme', raw);
  }
})();
//

head.b:skin:
:root{--accent:#ff6b00;--accent-hover:#ff8533;--accent-dim:rgba(255,107,0,0.15);--radius:10px;--radius-sm:6px;--radius-lg:16px;--shadow:0 2px 12px rgba(0,0,0,0.08);--shadow-lg:0 8px 32px rgba(0,0,0,0.12);--transition:0.25s ease;--font:'Segoe UI',-apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif;--container:1200px;--header-h:64px}
[data-theme="dark"]{color-scheme:dark;--bg:#1c1c21;--bg-elevated:#24242a;--bg-card:#2a2a32;--bg-card-hover:#32323b;--bg-input:#2e2e37;--border:#3a3a44;--border-light:#44444f;--text:#e2e2e6;--text-secondary:#9e9ea8;--text-muted:#6e6e78;--shadow:0 2px 12px rgba(0,0,0,0.25);--shadow-lg:0 8px 32px rgba(0,0,0,0.4);--select-option-bg:#17171f;--select-option-text:#f7f7fb;--genre-item-bg:#1a1a24;--genre-item-text:#e8e8ef;--genre-tag-text:#ffd9bf;--warning-bg:#3a2a1f;--warning-text:#ffe9d6;--warning-border:#ff8d3d;--warning-shadow:rgba(255,107,0,0.28)}
[data-theme="light"]{color-scheme:light;--bg:#eef1f6;--bg-elevated:#f8f9fc;--bg-card:#f8f9fc;--bg-card-hover:#f0f3f8;--bg-input:#e8ecf3;--border:#e0e0e6;--border-light:#eaeaef;--text:#202532;--text-secondary:#4d5566;--text-muted:#9a9aa4;--shadow:0 2px 12px rgba(0,0,0,0.06);--shadow-lg:0 8px 32px rgba(0,0,0,0.1);--select-option-bg:#f3f5fa;--select-option-text:#232836;--genre-item-bg:#eef2f8;--genre-item-text:#303849;--genre-tag-text:#8a3a00;--warning-bg:#fff0e4;--warning-text:#6b2f00;--warning-border:#e76700;--warning-shadow:rgba(231,103,0,0.16)}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--font);background:var(--bg);color:var(--text);line-height:1.6;min-height:100vh;transition:background var(--transition),color var(--transition)}
a{color:var(--accent);text-decoration:none;transition:color var(--transition)}
a:hover{color:var(--accent-hover)}
img{max-width:100%;height:auto;display:block}
ul,ol{list-style:none}
button,input,select,textarea{font-family:inherit;font-size:inherit;color:inherit;background:none;border:none;outline:none}
button{cursor:pointer}
h1,h2,h3,h4,h5,h6{line-height:1.3;font-weight:700}
.container{max-width:var(--container);margin:0 auto;padding:0 16px}
.site-main{min-height:calc(100vh - var(--header-h) - 200px);padding-bottom:40px}
.site-header{background:var(--bg-elevated);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:1000;height:var(--header-h);transition:background var(--transition),border-color var(--transition),transform 0.35s ease,opacity 0.35s ease}
.header-inner{display:flex;align-items:center;gap:20px;height:var(--header-h)}
.site-warning{background:var(--bg-elevated);border-bottom:1px solid var(--border)}
.site-warning .container{padding-top:10px;padding-bottom:10px}
.site-warning p{display:flex;align-items:center;gap:9px;margin:0;padding:9px 12px;border:1px solid var(--warning-border);border-left:4px solid var(--warning-border);border-radius:var(--radius-sm);background:var(--warning-bg);color:var(--warning-text);font-size:0.89rem;font-weight:500;line-height:1.6;letter-spacing:0.1px;box-shadow:0 2px 10px var(--warning-shadow)}
.site-warning-icon{display:inline-grid;flex:0 0 19px;width:19px;height:19px;place-items:center;border-radius:50%;background:var(--warning-border);color:#fff;font-size:0.75rem;font-weight:800;line-height:1;animation:site-warning-pulse 1.6s ease-in-out infinite}
@keyframes site-warning-pulse{0%,100%{opacity:1;transform:scale(1)}
50%{opacity:0.45;transform:scale(0.88)}}
@media (prefers-reduced-motion:reduce){.site-warning-icon{animation:none}}
.logo{display:inline-flex;flex:0 0 auto;align-items:center;justify-content:center;padding:0;color:var(--text);line-height:0;white-space:nowrap}
.logo-mark{display:block;width:88px;height:24px;background:currentColor;-webkit-mask:url('../images/logo-cg.png') center / contain no-repeat;mask:url('../images/logo-cg.png') center / contain no-repeat;transition:background-color var(--transition)}
.logo:hover{color:var(--accent)}
.main-nav{display:flex;align-items:center;gap:4px;flex:1}
.main-nav a,.nav-dropdown-btn{padding:8px 14px;border-radius:var(--radius-sm);color:var(--text-secondary);font-size:0.9rem;font-weight:500;transition:all var(--transition);white-space:nowrap}
.main-nav a:hover,.nav-dropdown-btn:hover{color:var(--accent);background:var(--accent-dim)}
.nav-dropdown{position:relative}
.nav-dropdown-btn{display:flex;align-items:center;gap:5px;cursor:pointer}
.nav-dropdown-menu{position:absolute;top:100%;left:0;background:var(--bg-elevated);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow-lg);min-width:160px;padding:6px;display:none;z-index:100}
.nav-dropdown-menu.show{display:block}
.nav-dropdown-menu a{display:block;padding:8px 14px;border-radius:var(--radius-sm);color:var(--text-secondary);font-size:0.88rem}
.nav-dropdown-menu a:hover{background:var(--accent-dim);color:var(--accent)}
.header-actions{display:flex;align-items:center;gap:10px;margin-left:auto}
.search-box{display:flex;align-items:center;background:var(--bg-input);border:1px solid var(--border);border-radius:50px;overflow:visible;transition:border-color var(--transition);position:relative}
.search-box:focus-within{border-color:var(--accent)}
.search-box input{width:280px;padding:8px 14px;background:transparent;font-size:0.88rem}
.search-box input::placeholder{color:var(--text-muted)}
.search-box button{padding:8px 12px;color:var(--text-muted);transition:color var(--transition)}
.search-box button:hover{color:var(--accent)}
.search-suggest{position:absolute;top:calc(100% + 6px);left:0;right:0;min-width:360px;background:var(--bg-elevated);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow-lg);z-index:1100;max-height:340px;overflow-y:auto;display:none}
.search-suggest.active{display:block}
.search-suggest-item{display:flex;align-items:center;gap:12px;padding:10px 14px;transition:background var(--transition);cursor:pointer;border-bottom:1px solid var(--border)}
.search-suggest-item:last-child{border-bottom:none}
.search-suggest-item:hover,.search-suggest-item.focused{background:var(--accent-dim)}
.search-suggest-item img{width:36px;height:48px;object-fit:cover;border-radius:var(--radius-sm);flex-shrink:0;background:var(--bg-input)}
.search-suggest-info{flex:1;min-width:0}
.search-suggest-title{font-size:0.88rem;font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.search-suggest-meta{display:flex;align-items:center;gap:8px;font-size:0.75rem;color:var(--text-muted);margin-top:2px}
.search-suggest-type{display:inline-block;padding:1px 7px;border-radius:50px;font-size:0.68rem;font-weight:700;text-transform:uppercase;background:var(--accent-dim);color:var(--accent)}
.search-suggest-chapter{font-size:0.75rem;color:var(--text-secondary)}
.search-suggest-empty{padding:20px 14px;text-align:center;font-size:0.85rem;color:var(--text-muted)}
.theme-toggle{width:38px;height:38px;display:flex;align-items:center;justify-content:center;border-radius:50%;color:var(--text-secondary);transition:all var(--transition)}
.theme-toggle:hover{background:var(--accent-dim);color:var(--accent)}
[data-theme="dark"] .icon-moon{display:none}
[data-theme="light"] .icon-sun{display:none}
.content-filter{position:relative;flex-shrink:0}
.content-filter-toggle{width:38px;height:38px;border:1px solid var(--border);border-radius:50%;background:var(--bg-card);color:var(--text-secondary);display:inline-flex;align-items:center;justify-content:center;position:relative;transition:all var(--transition)}
.content-filter-toggle:hover,.content-filter-toggle.has-active-filter{border-color:var(--accent);color:var(--accent);background:var(--accent-dim)}
.content-filter-count{position:absolute;top:-5px;right:-5px;min-width:17px;height:17px;padding:0 4px;border-radius:999px;background:var(--accent);color:#fff;font-size:0.62rem;font-weight:800;line-height:17px;text-align:center}
.content-filter-panel{position:absolute;top:calc(100% + 10px);right:0;width:min(340px,calc(100vw - 24px));padding:14px;border:1px solid var(--border);border-radius:var(--radius-lg);background:var(--bg-card);box-shadow:var(--shadow-lg);z-index:1000}
.content-filter-head,.content-filter-actions{display:flex;align-items:center;justify-content:space-between;gap:10px}
.content-filter-head{margin-bottom:10px}
.content-filter-close{width:28px;height:28px;border-radius:50%;color:var(--text-muted);font-size:1.2rem;line-height:1}
.content-filter-close:hover{color:var(--accent);background:var(--accent-dim)}
.content-filter-switch,.content-filter-genre{display:flex;align-items:center;gap:9px;color:var(--text-secondary);font-size:0.84rem;cursor:pointer}
.content-filter-switch{padding:9px 10px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--bg-input);justify-content:space-between}
.content-filter-main-switch input{position:absolute;opacity:0;pointer-events:none}
.content-filter-main-switch>span:last-child{flex:1 1 auto;color:var(--text);font-weight:700}
.content-filter-switch-ui{width:38px;height:20px;border-radius:999px;background:var(--border);position:relative;flex:0 0 auto;transition:background var(--transition)}
.content-filter-switch-ui::after{content:'';width:16px;height:16px;border-radius:50%;background:#fff;position:absolute;top:2px;left:2px;box-shadow:0 1px 4px rgba(0,0,0,0.25);transition:transform var(--transition)}
.content-filter-main-switch input:checked+.content-filter-switch-ui{background:var(--accent)}
.content-filter-main-switch input:checked+.content-filter-switch-ui::after{transform:translateX(18px)}
.content-filter-main-switch:has(input:checked){border-color:rgba(255,107,0,0.5);background:var(--accent-dim)}
.content-filter-genre input{accent-color:var(--accent)}
.content-filter-note,.content-filter-empty{margin:9px 0 0;color:var(--text-muted);font-size:0.76rem;line-height:1.45}
.content-filter-search{width:100%;height:38px;box-sizing:border-box;margin:10px 0;padding:0 12px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--bg-input);color:var(--text)}
.content-filter-search:disabled{opacity:0.7;cursor:not-allowed}
.content-filter-genres[hidden]{display:none}
.content-filter-genres{max-height:230px;overflow:auto;padding:0 4px 0 0;display:grid;gap:7px}
.content-filter-genre{display:flex;align-items:center;gap:10px;padding:9px 10px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--bg-input);color:var(--text);transition:border-color var(--transition),background var(--transition)}
.content-filter-genre[hidden]{display:none}
.content-filter-genre:hover{border-color:var(--accent);background:var(--accent-dim)}
.content-filter-genre span{flex:1 1 auto;min-width:0}
.content-filter-genre input{order:2;flex:0 0 auto}
.content-filter-genre:has(input:checked){border-color:rgba(255,107,0,0.5);background:var(--accent-dim)}
.content-filter-genre input:disabled{cursor:not-allowed}
.content-filter-empty{margin-top:10px;text-align:center}
.content-filter-actions{margin-top:12px}
.content-filter-saved{color:var(--text-muted);font-size:0.74rem;font-weight:700}
.mobile-menu-btn{display:none;flex-direction:column;gap:5px;width:38px;height:38px;align-items:center;justify-content:center;border-radius:var(--radius-sm)}
.mobile-menu-btn span{display:block;width:22px;height:2px;background:var(--text-secondary);transition:all var(--transition);border-radius:2px}
.mobile-menu-btn.active span:nth-child(1){transform:rotate(45deg) translateY(7px)}
.mobile-menu-btn.active span:nth-child(2){opacity:0}
.mobile-menu-btn.active span:nth-child(3){transform:rotate(-45deg) translateY(-7px)}
.breadcrumb{margin:20px 0 10px}
.breadcrumb ol{display:flex;flex-wrap:wrap;gap:4px;align-items:center}
.breadcrumb li{font-size:0.85rem;color:var(--text-muted)}
.breadcrumb li+li::before{content:'/';margin-right:4px;color:var(--text-muted)}
.breadcrumb a{color:var(--text-secondary)}
.breadcrumb a:hover{color:var(--accent)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:10px 22px;border-radius:var(--radius);font-weight:600;font-size:0.9rem;transition:all var(--transition);cursor:pointer;white-space:nowrap}
.btn-primary{background:var(--accent);color:#fff;box-shadow:0 4px 14px rgba(255,107,0,0.35)}
.btn-primary:hover{background:var(--accent-hover);color:#fff;box-shadow:0 6px 20px rgba(255,107,0,0.45);transform:translateY(-1px)}
.btn-outline{border:2px solid var(--accent);color:var(--accent);background:transparent}
.btn-outline:hover{background:var(--accent);color:#fff}
.btn-ghost{color:var(--text-secondary);background:var(--bg-input);border:1px solid var(--border)}
.btn-ghost:hover{border-color:var(--accent);color:var(--accent)}
.btn-sm{padding:6px 14px;font-size:0.82rem;border-radius:var(--radius-sm)}
.btn-lg{padding:14px 32px;font-size:1rem;border-radius:var(--radius)}
.comic-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:16px}
.comic-card{background:var(--bg-card);border-radius:var(--radius);overflow:hidden;transition:all var(--transition);border:1px solid var(--border);display:flex;flex-direction:column}
.comic-card:hover{background:var(--bg-card-hover);transform:translateY(-3px);box-shadow:var(--shadow-lg);border-color:var(--accent)}
.comic-card-cover{aspect-ratio:3/4;overflow:hidden;position:relative;background:var(--bg-input);display:block}
.comic-card-cover img{width:100%;height:100%;object-fit:cover;transition:transform 0.4s ease}
.comic-card:hover .comic-card-cover img{transform:scale(1.05)}
.comic-card-badges{position:absolute;inset:0;z-index:3;pointer-events:none}
.comic-card-badges .badge-type-ribbon{top:8px;left:-6px}
.comic-card-badges .badge-status{position:absolute;top:8px;right:8px}
.comic-card-body{padding:10px 10px 12px;display:flex;flex-direction:column;flex:1}
.comic-card-title{font-size:0.85rem;font-weight:600;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;color:var(--text);height:2.6em;/* fixed 2-line height */:}
.comic-card-title a{color:inherit}
.comic-card-title a:hover{color:var(--accent)}
.comic-card-chapter{font-size:0.78rem;color:var(--text-secondary);display:flex;align-items:center;justify-content:space-between;gap:4px;line-height:1.4;margin-top:auto;padding-top:6px;min-width:0;width:100%}
.comic-card-chapter a{display:block;min-width:0;max-width:100%;flex:1 1 auto;color:var(--accent);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.comic-card-chapter a:hover{color:var(--accent-hover)}
.comic-card-chapter .ch-time{font-size:0.68rem;color:var(--text-muted);white-space:nowrap;flex-shrink:0}
.badge-type{display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border-radius:4px;font-size:0.64rem;font-weight:800;letter-spacing:0.35px;color:#fff;line-height:1.4;text-shadow:0 1px 1px rgba(0,0,0,0.2)}
.badge-type img{width:14px;height:10px;object-fit:cover;border-radius:2px;box-shadow:0 0 0 1px rgba(255,255,255,0.25);flex-shrink:0}
.badge-type-ribbon{position:absolute;top:8px;left:-6px;padding:4px 10px 4px 12px;border-radius:0 8px 8px 0;font-size:0.64rem;font-weight:800;letter-spacing:0.25px;text-transform:uppercase;box-shadow:0 6px 12px rgba(0,0,0,.18);z-index:4}
.badge-type-ribbon::before{content:'';position:absolute;left:0;bottom:-6px;width:0;height:0;border-top:6px solid rgba(0,0,0,.35);border-left:6px solid transparent}
.badge-type-ribbon .badge-type-text{line-height:1}
.badge-type-manga{background:#e74c3c}
.badge-type-manhwa{background:#3498db}
.badge-type-manhua{background:#2ecc71}
.badge-pornhwa-ribbon{position:absolute;top:32px;left:-6px;padding:2px 8px 2px 10px;border-radius:0 6px 6px 0;font-size:0.48rem;font-weight:800;letter-spacing:0.4px;text-transform:uppercase;background:#e74c3c;color:#fff;box-shadow:0 3px 6px rgba(0,0,0,.18);z-index:4;line-height:1.2}
.badge-pornhwa-ribbon::before{content:'';position:absolute;left:0;bottom:-4px;width:0;height:0;border-top:4px solid rgba(0,0,0,.3);border-left:4px solid transparent}
.badge-status{display:inline-block;padding:2px 7px;border-radius:4px;font-size:0.68rem;font-weight:700;backdrop-filter:blur(4px)}
.status-ongoing{background:rgba(46,204,113,0.85);color:#fff}
.status-completed{background:rgba(52,152,219,0.85);color:#fff}
.section-header{display:flex;align-items:center;justify-content:space-between;margin:32px 0 20px;padding-bottom:12px;border-bottom:2px solid var(--border)}
.section-header h2{font-size:1.3rem;position:relative;padding-left:14px}
.section-header h2::before{content:'';position:absolute;left:0;top:2px;bottom:2px;width:4px;background:var(--accent);border-radius:2px}
.section-header .section-link{font-size:0.88rem;font-weight:600;color:var(--accent)}
.section-header .section-link:hover{color:var(--accent-hover)}
.hero-slider{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}
.hero-card{position:relative;border-radius:var(--radius-lg);overflow:hidden;aspect-ratio:16/10;background:var(--bg-card)}
.hero-card img{width:100%;height:100%;object-fit:cover}
.hero-card-overlay{position:absolute;bottom:0;left:0;right:0;padding:40px 20px 16px;background:linear-gradient(transparent,rgba(0,0,0,0.85));color:#fff}
.hero-card-overlay h3{font-size:1rem;font-weight:700;line-height:1.3;margin-bottom:4px}
.hero-card-overlay h3 a{color:#fff;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hero-card-overlay h3 a:hover{color:var(--accent)}
.hero-card-overlay .hero-meta{font-size:0.78rem;opacity:0.8;display:flex;gap:10px}
.hero-card-overlay .badge-type{font-size:0.56rem;padding:2px 6px;gap:4px}
.hero-card-overlay .badge-type img{width:11px;height:8px}
html[data-adult-mode="off"] .adult-sensitive-cover,html[data-detail-genre-filtered="1"] body .comic-detail .comic-cover,.comic-card[data-filter-hidden="1"] .comic-card-cover,.hero-card[data-filter-hidden="1"],.comic-cover[data-filter-hidden="1"]{position:relative;overflow:hidden}
html[data-adult-mode="off"] .comic-card[data-adult="1"] .comic-card-cover img,html[data-adult-mode="off"] .hero-card[data-adult="1"]>img,html[data-adult-mode="off"] .comic-cover[data-adult="1"]>img,html[data-adult-mode="off"] .search-suggest-item[data-adult="1"] .search-suggest-cover,html[data-detail-genre-filtered="1"] body .comic-detail .comic-cover>img,.comic-card[data-filter-hidden="1"] .comic-card-cover img,.hero-card[data-filter-hidden="1"]>img,.comic-cover[data-filter-hidden="1"]>img,.search-suggest-item[data-filter-hidden="1"] .search-suggest-cover{filter:blur(14px) saturate(0.75) brightness(0.85);transform:scale(1.03)}
html[data-adult-mode="off"] .adult-sensitive-cover::after,html[data-detail-genre-filtered="1"] body .comic-detail .comic-cover::after,.comic-card[data-filter-hidden="1"] .comic-card-cover::after,.hero-card[data-filter-hidden="1"]::after,.comic-cover[data-filter-hidden="1"]::after{content:'Ditutup';position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);padding:5px 10px;border-radius:999px;border:1px solid rgba(255,255,255,0.35);background:rgba(12,12,16,0.62);color:#fff;font-size:0.68rem;font-weight:700;letter-spacing:0.18px;pointer-events:none;z-index:2}
html[data-adult-mode="on"] .adult-sensitive-cover::after{content:none}
html[data-adult-mode="on"][data-detail-genre-filtered="1"] body .comic-detail .comic-cover::after,html[data-adult-mode="on"] .comic-cover[data-filter-hidden="1"]::after,.comic-card[data-filter-hidden="1"] .comic-card-cover::after,.hero-card[data-filter-hidden="1"]::after,.comic-cover[data-filter-hidden="1"]::after{content:'Ditutup'}
html[data-detail-genre-filtered="1"] body .adult-lock-hint[hidden],html[data-adult-mode="off"] body[data-comic-adult="1"] .adult-lock-hint[hidden]{display:block!important}
.genre-pills{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}
.genre-pill{padding:6px 16px;border-radius:50px;border:1px solid var(--border);background:var(--bg-card);color:var(--text-secondary);font-size:0.82rem;font-weight:500;transition:all var(--transition)}
.genre-pill:hover,.genre-pill.active{background:var(--accent);border-color:var(--accent);color:#fff}
.genre-pill.is-empty{background:var(--bg-input);color:var(--text-muted);border-color:var(--border);pointer-events:none}
.comic-detail{display:grid;grid-template-columns:260px 1fr;gap:32px;margin:24px 0}
