.page-content{max-width:800px;margin:32px auto;line-height:1.8;background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:40px 48px;box-shadow:var(--shadow)}
.page-content h1{font-size:2rem;margin-bottom:24px;padding-bottom:16px;border-bottom:2px solid var(--border);color:var(--text)}
