.contact-card{background:var(--bg-elevated);border:1px solid var(--border);border-radius:var(--radius);padding:24px;margin:20px 0}
.contact-card h3{font-size:1rem;margin-bottom:12px;color:var(--text);border-left:none;padding-left:0}
.contact-card p{margin-bottom:8px}
.text-accent{color:var(--accent)}
.text-muted{color:var(--text-muted)}
.text-center{text-align:center}
.mt-1{margin-top:8px}
.mt-2{margin-top:16px}
.mt-3{margin-top:24px}
.mb-1{margin-bottom:8px}
.mb-2{margin-bottom:16px}
.mb-3{margin-bottom:24px}
.flex{display:flex}
