 .search-box{position:absolute;top:50%;right:calc(100% + 8px);transform:translateY(-50%);order:0;width:40px;min-width:40px;height:40px;border-radius:999px;overflow:visible;padding:0;margin-left:0;background:transparent;border:0;border-radius:0;box-shadow:none;z-index:1200;transition:width var(--transition),border-color var(--transition),box-shadow var(--transition),background var(--transition)}
.search-box input{width:0;min-width:0;padding:0;opacity:0;pointer-events:none;transition:width var(--transition),opacity var(--transition),padding var(--transition)}
.search-box button{width:38px;height:38px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:0}


.search-box.is-open{position:fixed;top:calc(var(--header-h) + 8px);left:12px;right:12px;width:auto;min-width:0;height:42px;transform:none;padding:0 10px 0 12px;border:1px solid var(--border);border-radius:999px;background:var(--bg-elevated);box-shadow:var(--shadow-lg)}


.search-box.is-open input{width:100%;min-width:0;padding:9px 8px 9px 0;opacity:1;pointer-events:auto}

