.comic-card-badges .badge-pornhwa-ribbon{top:26px;left:-5px;font-size:0.44rem;padding:1px 6px 1px 8px}
.comic-cover-badges .badge-type-ribbon{top:8px;left:-5px;font-size:0.56rem;padding:3px 8px 3px 10px}
.comic-cover-badges-right{top:8px;right:8px;gap:4px}
.comic-cover-badges .badge-pornhwa-ribbon{top:28px;font-size:0.46rem;padding:2px 8px 2px 10px}
