@keyframes fadeIn{from{opacity:0;transform:translateY(10px)}
to{opacity:1;transform:translateY(0)}}
.fade-in{animation:fadeIn 0.4s ease forwards}
body,.site-header,.site-footer,.comic-card,.btn-ghost,.reader-header,.filter-group select,.form-input,.page-btn{transition:background var(--transition),color var(--transition),border-color var(--transition),box-shadow var(--transition)}
::selection{background:var(--accent);color:#fff}
::-webkit-scrollbar{width:8px}
::-webkit-scrollbar-track{background:var(--bg)}
::-webkit-scrollbar-thumb{background:var(--border);border-radius:4px}
::-webkit-scrollbar-thumb:hover{background:var(--accent)}
.static-page-card{background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius);padding:24px;margin:20px 0}
.static-page-card h3{font-size:1rem;margin-bottom:12px;color:var(--accent)}
.static-page-card ul{padding-left:20px;list-style:disc}
.static-page-card ul li{margin-bottom:8px;color:var(--text-secondary)}
.static-page-card p{color:var(--text-secondary);line-height:1.7}
.contact-card{display:flex;align-items:center;gap:16px;background:var(--bg-card);border:1px solid var(--border);border-radius:var(--radius);padding:20px 24px;margin:16px 0;transition:border-color var(--transition)}
.contact-card:hover{border-color:var(--accent)}
.contact-card svg{flex-shrink:0;color:var(--accent)}
.contact-card-info{min-width:0}
.contact-card-info strong{display:block;margin-bottom:2px;color:var(--text)}
.contact-card-info a{color:var(--accent)}
.notification-menu{position:relative}
.notification-toggle{position:relative;width:36px;height:36px;border:0;border-radius:9px;background:transparent;color:var(--text);display:grid;place-items:center;cursor:pointer}
.notification-toggle:hover{background:var(--bg-card-hover)}
.notification-badge{position:absolute;right:5px;top:5px;width:9px;height:9px;border-radius:50%;background:#f04444;border:2px solid var(--bg-elevated)}
.notification-panel{position:absolute;right:0;top:43px;width:min(390px,calc(100vw - 24px));max-height:420px;overflow-y:auto;overscroll-behavior:contain;background:var(--bg-card);color:var(--text);border:1px solid var(--border);border-radius:10px;box-shadow:var(--shadow-lg);z-index:1000;scrollbar-width:thin;scrollbar-color:var(--border-light) transparent}
.notification-head{position:sticky;top:0;display:flex;align-items:center;gap:10px;padding:9px 11px;background:var(--bg-card);border-bottom:1px solid var(--border);z-index:1}
.notification-head>strong{margin-right:auto}
.notification-head>button{border:0;background:none;color:var(--text);font-size:21px;cursor:pointer}
.notification-tabs{display:flex;gap:3px;padding:3px;border-radius:8px;background:var(--bg-elevated)}
.notification-tabs button{position:relative;padding:5px 9px;border:0;border-radius:6px;background:transparent;color:var(--text-secondary);font-size:.72rem;font-weight:650;cursor:pointer}
.notification-tabs button.is-active{background:var(--bg-card);color:var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.1)}
.notification-tab-dot{position:absolute;top:3px;right:3px;width:6px;height:6px;border-radius:50%;background:#f04444}
.notification-item{display:block;padding:11px 13px;border-bottom:1px solid var(--border);color:var(--text);text-decoration:none}
.notification-item:hover{background:var(--bg-card-hover)}
.notification-item strong{display:block;margin-bottom:3px;font-size:.92rem;overflow-wrap:anywhere}
.notification-item p{margin:0;color:var(--text-secondary);font-size:.84rem;line-height:1.45;max-height:8.7em;overflow-y:auto;overflow-wrap:anywhere;white-space:pre-wrap;scrollbar-width:thin}
.notification-empty{margin:0;color:var(--text-secondary);font-size:.84rem;line-height:1.4}
.notification-item time{display:block;margin-top:5px;color:var(--text-muted);font-size:.72rem}
@media(max-width:640px){.notification-panel{position:fixed;top:60px;right:8px;left:8px;width:auto;max-height:62vh}
.notification-head{gap:7px}
.notification-tabs button{padding:5px 7px}}
