.comic-card.card-js[data-adult='1']{overflow:visible}
.comic-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:10px!important;width:100%;align-items:start}
@media (min-width:768px){.comic-grid{grid-template-columns:repeat(4,minmax(0,1fr))!important}}
@media (min-width:900px){.comic-grid{grid-template-columns:repeat(6,minmax(0,1fr))!important}}
