.logo-img{max-height:40px;width:auto;display:block}
.logo-img.logo-light{display:none}
[data-theme="light"] .logo-img.logo-dark{display:none}
[data-theme="light"] .logo-img.logo-light{display:block}
[data-theme="light"] .logo-img.logo-invert{filter:invert(1) hue-rotate(180deg)}
html{overflow-x:hidden;max-width:100%}
body{overflow-x:clip;max-width:100%}
.site-main,.site-main>.container,.site-footer{max-width:100%}
.site-main .section,.site-main .widget{min-width:0;max-width:100%}
.section-header h1 .section-count{font-size:.8rem;font-weight:400;color:var(--text-muted);margin-left:4px}
.comic-card{min-width:0!important;width:100%!important;overflow:hidden}
.comic-card-cover{display:block!important;position:relative;width:100%!important;aspect-ratio:160 / 220;overflow:hidden}
.comic-card-cover>img{display:block!important;width:100%!important;height:100%!important;max-width:none!important;object-fit:cover}
.comic-card-badges{max-width:100%;pointer-events:none}
.comic-card-body{min-width:0;padding:7px 2px 2px!important}
.comic-card-title{margin:0!important;font-size:.78rem!important;line-height:1.35!important;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}
.comic-card-title a{display:block;overflow:hidden;text-overflow:ellipsis}
.comic-card-chapter{display:flex!important;align-items:center;justify-content:space-between;gap:5px;margin-top:5px!important;font-size:.68rem!important;line-height:1.2}
.comic-card-chapter>a{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.comic-card-chapter .ch-time{flex:0 0 auto;font-size:.62rem;white-space:nowrap}
@media (max-width:420px){.comic-grid{gap:8px!important}
.comic-card-title{font-size:.74rem!important}
.comic-card-chapter{font-size:.64rem!important}
.comic-card-chapter .ch-time{font-size:.58rem}}
@media (min-width:768px){.comic-grid{gap:14px!important}
.comic-card-title{font-size:.86rem!important}}
.comic-card-chapter .card-chapter-link{font-weight:700!important;color:var(--accent)!important}
.comic-card-chapter .ch-time{font-size:.62rem!important;color:var(--text-muted,#8b98a8)!important;white-space:nowrap}
.comic-cover-col{position:sticky;top:calc(var(--header-h) + 16px);align-self:start;min-width:0}
.comic-cover-col .comic-cover{position:relative;top:auto}
@media (max-width:768px){.comic-cover-col{position:relative;top:auto}}
#relatedSeries{grid-column:1/-1;min-width:0;width:100%;margin-top:32px}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
@media (prefers-reduced-motion:reduce){*,::before,::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
#comments{margin:24px 0 0;padding:0;background:none;border:0}
#comments>.title{margin:0 0 10px;font-size:1.1rem;font-weight:800;color:var(--text)}
#comments ol,#comments ul,#comments li{list-style:none;margin:0;padding:0}
#comments .comment-thread{margin:0}
#comments li.comment{position:relative;margin:0 0 6px}
#comments .avatar-image-container{position:absolute;left:10px;top:10px;z-index:1;float:none;width:38px;height:38px;margin:0;background:#fff;overflow:hidden}
#comments .avatar-image-container img{display:block;width:38px;height:38px;max-width:none;object-fit:cover}
#comments .comment-block{min-width:0;min-height:58px;margin:0;padding:10px 10px 10px 58px;background:var(--bg-card)}
#comments .comment-header{display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:0 10px;margin:0}
#comments .comment-header .user,#comments .comment-header .user a{font-style:normal;font-weight:600;font-size:.88rem;color:var(--text);text-decoration:none}
#comments .comment-header .icon{display:none}
#comments .datetime,#comments .datetime a{font-size:.72rem;color:var(--text-secondary);text-decoration:none}
#comments .comment-content{margin:4px 0 6px;font-size:.92rem;line-height:1.5;color:var(--text);overflow-wrap:anywhere}
#comments .comment-content img{max-width:100%;height:auto}
#comments .comment-actions{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:6px;margin:0}
#comments .comment-actions a{display:inline-block;padding:4px 10px;background:var(--bg);color:var(--text);border-radius:6px;font-size:.76rem;line-height:1.2;text-decoration:none}
#comments .comment-actions a:hover{color:var(--accent)}
#comments .comment-actions .item-control{display:inline-flex;gap:6px}
#comments .comment-replies{margin:0;padding:0}
#comments .comment-replies ol{margin:0;padding:0}
#comments .thread-toggle{display:block;margin:8px 0 6px;font-size:.88rem;color:var(--text-secondary)}
#comments .comment-replies .comment-replies .thread-toggle,#comments .thread-arrow,#comments .continue,#comments .loadmore,#comments .comment-form h4,#comments #comment-post-message{display:none}
#comments .thread-count a{color:inherit;text-decoration:none;cursor:default;pointer-events:none}
#comments .comment-replies .comment-block{background:var(--bg-elevated)}
#comments .comment-replybox-single,#comments .comment-replybox-thread{margin:0;padding:0}
#comments .comment-replybox-single:has(iframe),#comments .comment-replybox-thread:has(iframe){margin:6px 0;padding:8px;background:var(--bg-card)}
#comments .comment-form{margin:10px 0 0;padding:8px;background:var(--bg-card)}
#comments .comment-form iframe,#comments #comment-editor{width:100%!important;max-width:100%!important;border:0}
@media (max-width:480px){#comments .avatar-image-container,#comments .avatar-image-container img{width:34px;height:34px}
#comments .comment-block{padding-left:52px}}
.content-filter-genre[hidden]{display:none}

.comic-actions { display: flex; gap: 12px; margin: 24px 0; flex-wrap: wrap; }
.comic-share { margin: 10px 0 14px; } 
.share-title { font-size: 0.78rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px; color: var(--text-muted); margin-bottom: 8px; } 
.share-links { display: flex; flex-wrap: wrap; gap: 8px; } 
.share-btn { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; padding: 0; border-radius: var(--radius-sm); border: 1px solid var(--border); background: var(--bg-card); color: var(--text); } 
.share-btn svg { width: 16px; height: 16px; } 
.share-btn:hover { border-color: var(--accent); color: var(--accent); background: var(--accent-dim); }

/* Mengatur agar posisi ke tengah (center) saat di layar HP / Mobile */
@media (max-width: 768px) {
  .comic-actions, .share-links {
    justify-content: center;
  }
  .share-title {
    text-align: center;
  }
}
/* Chapter List */
.chapter-list {
  margin: 24px 0;
}
.chapter-list-header {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  padding: 12px 0; border-bottom: 2px solid var(--border);
  margin-bottom: 8px;
}
.chapter-list-head h2 {
  font-size: 1.2rem;
  margin-bottom: 2px;
}
.chapter-last-info {
  font-size: 0.78rem;
  color: var(--text-muted);
}
.chapter-search-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 12px 0;
  max-width: 380px;
}
.chapter-search-input {
  flex: 1 1 auto;
  min-width: 0;
  height: 40px;
}
.chapter-sort-toggle {
  width: 42px;
  height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-input);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition);
}
.chapter-sort-toggle:hover,
.chapter-sort-toggle:focus-visible {
  border-color: var(--accent);
  color: var(--accent);
  outline: none;
}
.chapter-sort-toggle .sort-icon {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.chapter-sort-toggle .sort-icon-asc {
  display: none;
}
.chapter-sort-toggle[data-sort="asc"] .sort-icon-desc {
  display: none;
}
.chapter-sort-toggle[data-sort="asc"] .sort-icon-asc {
  display: block;
}

/* Adult Lock Hint */
.adult-lock-hint {
  margin: 8px 0 10px;
  padding: 10px 12px;
  border: 1px solid var(--warning-border);
  border-left: 4px solid var(--warning-border);
  border-radius: var(--radius-sm);
  background: var(--warning-bg);
  color: var(--warning-text);
  font-size: 0.82rem;
  line-height: 1.5;
}
.adult-inline-toggle {
  margin-left: 8px;
  border: 0;
  background: transparent;
  color: var(--accent);
  font-weight: 700;
  text-decoration: underline;
}

/* Opacity untuk konten yang terkena filter konten dewasa */
html[data-adult-mode="off"] body[data-comic-adult="1"] .chapter-grid .ch-grid-item,
html[data-detail-genre-filtered="1"] body .chapter-grid .ch-grid-item,
body[data-content-filtered="1"] .chapter-grid .ch-grid-item {
  opacity: 0.72;
}
html[data-adult-mode="off"] body[data-comic-adult="1"] .chapter-grid .ch-grid-item:hover,
html[data-detail-genre-filtered="1"] body .chapter-grid .ch-grid-item:hover,
body[data-content-filtered="1"] .chapter-grid .ch-grid-item:hover {
  background: var(--bg-card);
  color: var(--text);
  border-color: var(--border);
}

/* Chapter grid */
.chapter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
  gap: 8px;
  max-height: 500px;
  overflow-y: auto;
  padding: 4px;
}
.chapter-grid::-webkit-scrollbar { width: 6px; }
.chapter-grid::-webkit-scrollbar-track { background: transparent; }
.chapter-grid::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
.chapter-grid::-webkit-scrollbar-thumb:hover { background: var(--accent); }

/* Tombol Chapter (Grid Item) */
.ch-grid-item {
  display: block;
  min-width: 0;
  height: 38px;
  line-height: 20px;
  padding: 8px 10px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.82rem; font-weight: 600;
  color: var(--text);
  text-align: left;
  transition: all var(--transition);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.ch-grid-item:hover {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

/* Read chapters (Penanda chapter sudah dibaca) */
.ch-grid-item.is-read {
  background: rgba(148,163,184,0.08);
  color: var(--text-muted);
  border-color: var(--border-light);
  text-decoration: line-through;
  text-decoration-thickness: 1.5px;
  opacity: 0.95;
}
.ch-grid-item.is-read:hover {
  background: rgba(148,163,184,0.14);
  color: var(--text-secondary);
  border-color: var(--border);
}

/* Mobile Responsiveness */
@media (max-width: 768px) {
  .chapter-search-row {
    max-width: none;
  }
}

