b:with.script:
(function() {
  var el = document.getElementById('ch-');
  if(el) {
    var txt = el.textContent.trim();
    // Jika label chapter kosong, default ke tulisan "Terbaru"
    // Jika ada label "Chapter X", akan otomatis diganti menjadi "Ch. X"
    el.textContent = txt === '' ? 'Terbaru' : txt.replace(/^(Chapter|Ch\.|Ch)\s*/i, 'Ch. ');
  }
})();
